// SPDX-License-Identifier: MIT
// The kernel library embedded in the runtime (generated by clean/rr_f/runtime/tools/build.py: DXIL of every kernel,
// compiled with clean/dx12/build_dx12.py's exact arithmetic mode).
#pragma once
#include <stdint.h>

struct RrKernelBlob {
  const char* name;
  uint32_t nargs;
  const unsigned char* data;
  uint32_t size;
};
extern const RrKernelBlob kRrKernels[];
extern const uint32_t kRrKernelCount;
extern const int kRrInFoldX;   // stageex.IN0 (exact body) computes the front-end MLP from the codes too (clean/rr-f-lw-fold)
extern const int kRrInFold;    // stagee.IN0 computes the front-end MLP from the codes (no input.mlp.e dispatch)
extern const int kRrE1Direct;   // stage.E1 reads IN0's y2 directly (gpu/stage.py e1_direct): no regroup dispatch
extern const unsigned kRrDflowMaskX;  // stagedx.<stage> (exact body) has the dataflow form for these stages (clean/rr-f-s13x-x-flow)
extern const unsigned kRrDflowMask;   // staged.<stage> has the dataflow form (rr_dflow.hlsli) for these stages (clean/rr-f-s12-dflow)
